        unsigned values[] = {1};
        assert(fabs(total(values, 1) - 800) < 1e-9);
    }
    {
        unsigned values[] = {2, 2};
        assert(fabs(total(values, 2) - 1600) < 1e-9);
    }
    {
        unsigned values[] = {0};
        assert(fabs(total(values, 0) - 0) < 1e-9);
    }
    {
        unsigned values[] = {1, 2};
        assert(fabs(total(values, 2) - 1520) < 1e-9);
    }
    {
        unsigned values[] = {1, 2, 3};
        assert(fabs(total(values, 3) - 2160) < 1e-9);
    }
    {
        unsigned values[] = {1, 2, 3, 4};
        assert(fabs(total(values, 4) - 2560) < 1e-9);
    }
